begin;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('exports','exports',false,2147483648,array['application/zip']);
alter table public.export_jobs add column bytes bigint not null default 0;
alter table public.export_jobs add column reserved_bytes bigint not null default 0;
alter table public.export_jobs add column attempt integer not null default 0;
alter table public.export_jobs add column expires_at timestamptz not null default now()+interval '24 hours';
create function public.request_export(job uuid) returns public.export_jobs language plpgsql security definer set search_path=public as $$declare j public.processing_jobs;x public.export_jobs;u public.band_usage;e public.entitlements;n bigint;begin
 select * into j from public.processing_jobs where id=job;if j.status<>'completed' or not public.band_permission(j.band_id,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Export permission denied';end if;
 select * into u from public.band_usage where band_id=j.band_id for update;select * into x from public.export_jobs where processing_job_id=job for update;if found and x.status in ('queued','processing','completed') then return x;end if;
 select * into e from public.entitlements where band_id=j.band_id;select coalesce(sum((v->>'bytes')::bigint),0)+65536 into n from jsonb_array_elements(j.results)v;if u.stored_bytes+u.reserved_bytes+n>e.storage_limit then raise exception 'BR:Not enough space for temporary ZIP. Download individual stems instead.';end if;
 insert into public.export_jobs(band_id,processing_job_id,reserved_bytes)values(j.band_id,job,n) on conflict(processing_job_id) do update set status='queued',error=null,reserved_bytes=n,bytes=0,attempt=0,expires_at=now()+interval '24 hours' returning * into x;update public.band_usage set reserved_bytes=reserved_bytes+n where band_id=j.band_id;return x;end$$;
create function public.claim_export(hash text) returns jsonb language plpgsql security definer set search_path=public as $$declare x public.export_jobs;begin select * into x from public.export_jobs where expires_at>now() and attempt<3 and (status='queued' or status='processing' and lease_expires_at<now()) for update skip locked limit 1;if not found then return null;end if;update public.export_jobs set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '10 minutes',object_key='bands/'||band_id||'/exports/'||id||'.zip' where id=x.id returning * into x;return to_jsonb(x);end$$;
create function public.finish_export(job uuid,hash text,size bigint,job_error text default null) returns void language plpgsql security definer set search_path=public as $$declare x public.export_jobs;begin select * into x from public.export_jobs where id=job for update;if x.status='completed' then return;end if;if x.status<>'processing' or x.lease_hash<>hash or x.lease_expires_at<now() then raise exception 'BR:Stale export';end if;if size<0 or size>x.reserved_bytes then raise exception 'BR:Export exceeds reservation';end if;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-x.reserved_bytes),stored_bytes=stored_bytes+case when job_error is null then size else 0 end where band_id=x.band_id;update public.export_jobs set status=case when job_error is null then 'completed'::public.job_state else 'failed'::public.job_state end,bytes=case when job_error is null then size else 0 end,reserved_bytes=0,lease_hash=null,error=left(job_error,500) where id=job;end$$;
create function public.export_cleanup() returns trigger language plpgsql security definer set search_path=public as $$begin if old.object_key is not null then insert into public.cleanup_jobs(band_id,bucket,object_key)values(old.band_id,'exports',old.object_key);end if;update public.band_usage set stored_bytes=greatest(0,stored_bytes-old.bytes),reserved_bytes=greatest(0,reserved_bytes-old.reserved_bytes) where band_id=old.band_id;return old;end$$;
create trigger export_cleanup before delete on public.export_jobs for each row execute function public.export_cleanup();
create or replace function public.reconcile_usage(b uuid) returns void language plpgsql security definer set search_path=public as $$declare total bigint;begin perform 1 from public.band_usage where band_id=b for update;select coalesce(sum(bytes),0) into total from public.audio_assets where band_id=b and status='verified';select total+coalesce(sum(bytes),0) into total from public.export_jobs where band_id=b and status='completed';update public.band_usage set stored_bytes=total,updated_at=now() where band_id=b;end$$;
revoke execute on function public.request_export(uuid),public.claim_export(text),public.finish_export(uuid,text,bigint,text),public.export_cleanup() from public,anon,authenticated;
grant execute on function public.request_export(uuid) to authenticated;
grant execute on function public.request_export(uuid),public.claim_export(text),public.finish_export(uuid,text,bigint,text),public.export_cleanup() to service_role;
commit;
